package com.printflow.identity;
import java.util.*;import java.nio.file.*;import java.net.*;import java.net.http.*;import java.nio.charset.StandardCharsets;import java.time.Duration;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import org.springframework.core.env.StandardEnvironment;import tools.jackson.databind.json.JsonMapper;
/** Read-only provider reconciliation plus one signed duplicate delivery against synthetic local data. */
public class CapturedPaymentEvidence {
 public static void main(String[] args)throws Exception{
  var json=JsonMapper.builder().build();String url=System.getenv("DB_URL");if(url==null||!url.startsWith("jdbc:postgresql://127.0.0.1:5434/"))throw new IllegalStateException("Native test database required");var db=new JdbcTemplate(new DriverManagerDataSource(url,System.getenv("DB_USERNAME"),System.getenv("DB_PASSWORD")));UUID lead=UUID.fromString(System.getenv("APP_INVOICE_EVIDENCE_LEAD"));if(!db.queryForObject("select exists(select 1 from enquiries where id=? and customer_name like 'Synthetic%' and email like '%@example.test')",Boolean.class,lead))throw new IllegalStateException("Synthetic enquiry required");var api=new com.printflow.customer.RazorpayClient(new StandardEnvironment(),json);api.enabled();var receipts=db.queryForList("select c.provider_payment,g.provider_order,g.purpose,r.receipt_number,r.amount_paise from gateway_captures c join gateway_orders g on g.id=c.order_id join payment_receipts r on r.id=c.receipt_id where g.enquiry_id=? order by r.receipt_number",lead);if(receipts.size()!=2)throw new IllegalStateException("Two captured gateway receipts required");var verified=new ArrayList<Map<String,Object>>();long paid=0;for(var r:receipts){var remote=api.payment(r.get("provider_payment").toString());long amount=((Number)r.get("amount_paise")).longValue();if(!"captured".equals(remote.get("status"))||!Boolean.TRUE.equals(remote.get("captured"))||!r.get("provider_order").equals(remote.get("order_id"))||!"INR".equals(remote.get("currency"))||((Number)remote.get("amount")).longValue()!=amount)throw new IllegalStateException("Provider capture mismatch");paid+=amount;verified.add(Map.of("paymentId",r.get("provider_payment"),"orderId",r.get("provider_order"),"receiptNumber",r.get("receipt_number"),"purpose",r.get("purpose"),"amountPaise",amount,"providerState","captured","currency","INR"));}
  long total=db.queryForObject("select total_paise from quote_versions where enquiry_id=? and state='ACCEPTED'",Long.class,lead);if(paid!=total)throw new IllegalStateException("Balance is not settled");String state=db.queryForObject("select state from fulfilment_work where enquiry_id=?",String.class,lead);if(!"DELIVERED".equals(state))throw new IllegalStateException("UI delivery journey incomplete");var r=receipts.getFirst();byte[] body=json.writeValueAsBytes(Map.of("event","payment.captured","payload",Map.of("payment",Map.of("entity",Map.of("id",r.get("provider_payment"),"order_id",r.get("provider_order"))))));var mac=javax.crypto.Mac.getInstance("HmacSHA256");mac.init(new javax.crypto.spec.SecretKeySpec(System.getenv("RAZORPAY_WEBHOOK_SECRET").getBytes(StandardCharsets.UTF_8),"HmacSHA256"));String signature=HexFormat.of().formatHex(mac.doFinal(body));var response=HttpClient.newHttpClient().send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:8080/api/public/payments/razorpay/webhook")).timeout(Duration.ofSeconds(10)).header("Content-Type","application/json").header("X-Razorpay-Signature",signature).POST(HttpRequest.BodyPublishers.ofByteArray(body)).build(),HttpResponse.BodyHandlers.discarding());if(response.statusCode()!=200||db.queryForObject("select count(*) from payment_receipts where enquiry_id=?",Integer.class,lead)!=2)throw new IllegalStateException("Duplicate webhook changed receipt count");Files.writeString(Path.of("..",".local","razorpay-capture-evidence.json"),json.writeValueAsString(Map.of("receipts",verified,"totalPaise",total,"paidPaise",paid,"balancePaise",0,"fulfilment",state,"signedDuplicateWebhookStatus",response.statusCode(),"receiptCountAfterReplay",2)));System.out.println("Official provider confirms two captured TEST payments; balance zero, delivery confirmed, signed duplicate webhook adds no receipt.");
 }
}
